def lexicographically_minimum_coloring(n, m):
    # Initialize the table with empty cells
    table = [['' for _ in range(m)] for _ in range(n)]

    # Function to check if a region is a square
    def is_square_region(x, y, size, color):
        for i in range(size):
            for j in range(size):
                if table[x + i][y + j] != '' and table[x + i][y + j] != color:
                    return False
        return True

    # Fill the table with the lexicographically minimum coloring
    color = 'A'
    for size in range(1, min(n, m) + 1):
        for i in range(n - size + 1):
            for j in range(m - size + 1):
                if table[i][j] == '':
                    if is_square_region(i, j, size, color):
                        for x in range(i, i + size):
                            for y in range(j, j + size):
                                table[x][y] = color
                        color = chr(ord(color) + 1)

    # Convert the table to a single string
    result = ''.join(''.join(row) for row in table)
    return result

